@MvPowerSeries.min_weightedOrder_le_add : ∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ)
  {f g : MvPowerSeries σ R},
  min (MvPowerSeries.weightedOrder w f) (MvPowerSeries.weightedOrder w g) ≤ MvPowerSeries.weightedOrder w (f + g)

@MvPowerSeries.le_weightedOrder_prod : ∀ {σ : Type u_1} {R : Type u_2} [inst : CommSemiring R] {ι : Type u_3}
  (w : σ → ℕ) (f : ι → MvPowerSeries σ R) (s : Finset ι),
  ∑ i ∈ s, MvPowerSeries.weightedOrder w (f i) ≤ MvPowerSeries.weightedOrder w (∏ i ∈ s, f i)

@MvPowerSeries.weightedOrder_mul : ∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] [NoZeroDivisors R] (w : σ → ℕ)
  (f g : MvPowerSeries σ R),
  MvPowerSeries.weightedOrder w (f * g) = MvPowerSeries.weightedOrder w f + MvPowerSeries.weightedOrder w g
